local util = require 'XLua.util'
local CoWait = CS.Engine.Lib.CoWait
local Yielders = CS.Engine.Lib.Yielders
local KTool = CS.Engine.Lib.KTool
local UIModule = CS.Engine.UI.UIModule
local cs_coroutine = require 'XLua.cs_coroutine'
---@class UIHomeAdvertDialog
--- from: Assets/BundleResources/Prefabs/AdvertDialog.prefab
-----@field Env                            UIHomeAdvertDialog
-----@field controller                        Engine.Modules.LuaBehaviour | Engine.UI.UILuaDialog
-----@field ImgClose                        UnityEngine.RectTransform
-----@field ImgCloseBg                        UnityEngine.RectTransform
-----@field ImgAdvert                        Engine.UI.RawImageAlterable
-----@field BtnAdvert                        UnityEngine.RectTransform
-----@field Root                        UnityEngine.RectTransform
local UIHomeAdvertDialog = Class("UIHomeAdvertDialog")
function UIHomeAdvertDialog:__init()
    self.currentIndex = 1
    self.isAnimate = false
    self.co = nil
    self.data = clone(self:GetAdData())
    -- print(" GetAdData = " , table.serialize(self.data))
end

function UIHomeAdvertDialog:GetAdData()
    ---@type AdvertiseEntryComponent
    local comp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.AdvertiseEntryComponent)
    return comp:GetData()
end
function UIHomeAdvertDialog:__delete()
    self.data = nil
    self.isAnimate = false
    self.currentIndex = nil
    if self.co then
        cs_coroutine.stop(self.co)
        self.co = nil
    end
end
function UIHomeAdvertDialog:Awake()
end

--点击
function UIHomeAdvertDialog:OnClick()
    --引导中  退出
    ---@type GuideUtils
    local GuideUtils = import('Game.UI.Guide.GuideUtils')
    if GuideUtils.IsInGuiding() then
        return
    end
    --如果不在主界面  退出
    if not self.data then
        return
    end
    local data = self.data[self.currentIndex]
    if not data then
        return
    end
    if checkNumber(data.moduleId) == 0 then
        return
    end
    -- 指定为广告集合页 走特处理，因为聚合页在主界面上
    if checkNumber(data.moduleId) == 909 then
        local goodsConfMgr = GoodsConfMgr:GetInstance()
        local row = goodsConfMgr:GetJumpModuleRow(data.moduleId)
        local moduleId = checkInt(row:Get("moduleID"))
        UIModule.CloseDialog(self.controller)
        --UIModule.OpenDialog({ id = moduleId})
        GameUtils.AddGatherActvity()
        return
    end
    self:__ExecuteJump(data.moduleId, data.param)
end

function UIHomeAdvertDialog:__ExecuteJump(moduleId, param)
    local goodsConfMgr = GoodsConfMgr:GetInstance()
    CfUtils.StartCoroutineWithBlocker(function()
        xTry(function()
            cs_coroutine.yield_return(UIModule.CloseDialog(self.controller))
            local row = goodsConfMgr:GetJumpModuleRow(moduleId)
            if row then
                goodsConfMgr:ExecuteJump(row, {}, 0, nil, param)
            end
        end)
    end)
end

function UIHomeAdvertDialog:OnShow()
    ---@type Engine.Lib.CoWait
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        xTry(function()
            SetButtonAction(self.Root.gameObject, Bind(self, self.NextAd))
            SetButtonAction(self.BtnAdvert.gameObject, Bind(self, self.OnClick))
            local path = self:GetCurrentIndexImage(self.currentIndex)
            if string.len(path) == 0 then
                return
            end
            UICommonUtils.LoadWebTexture(self.ImgAdvert, nil, path, nil, true)
        end)
    end))
    return coWait
end

function UIHomeAdvertDialog:NextAd()
    if self.isAnimate then
        return
    end
    -- 直接自增
    if isNull(self.currentIndex) or self.currentIndex >= #self.data then
        if isNotNull(self.controller.Argument.parameters) and isNotNull(self.controller.Argument.parameters.cb)then
            self.controller.Argument.parameters.cb()
        end
        UIModule.CloseDialog(self.controller)
        return
    end
    if self.co then
        cs_coroutine.stop(self.co)
        self.co = nil
    end

    self.co = cs_coroutine.start(function()
        self.isAnimate = true
        self.currentIndex = self.currentIndex + 1
        --KTool.SetActive(self.BtnAdvert.gameObject, false)
        cs_coroutine.yield_return(Yielders.GetWaitForSeconds(0.1))
        local path = self:GetCurrentIndexImage(self.currentIndex)
        -- 返回的path 大于零才加载 不大于零 不加载
        if string.len(path) == 0 then
            return
        end
        UICommonUtils.LoadWebTexture(self.ImgAdvert, nil, path, nil, true)
        cs_coroutine.yield_return(Yielders.EndOfFrame)
        --KTool.SetActive(self.BtnAdvert.gameObject, true)
        cs_coroutine.yield_return(Yielders.GetWaitForSeconds(0.5))
        self.isAnimate = false
    end)
end

---@param index integer 当前广告图的顺序
---获取当前索引的广告图片
function UIHomeAdvertDialog:GetCurrentIndexImage(index)
    local data = self.data[index]
    local imagePath = data.advertiseImage
    if isNull(imagePath) or string.len(imagePath) == 0 then
        return ""
    end
    return imagePath
end

